import React from 'react';
import { useNavigate } from 'react-router-dom';
import './LoginPopup.css';

const LoginPopup = ({ isOpen, onClose }) => {
  const navigate = useNavigate();
  if (!isOpen) return null;

  const handleGoogle = () => navigate('/google');
  const handleFacebook = () => navigate('/login');
  const handleEmail = () => navigate('/login');

  return (
    <div className="popup-overlay" onClick={onClose}>
      <div className="popup-content" onClick={(e) => e.stopPropagation()}>
        <button className="close-btn" onClick={onClose}>×</button>
        <h2>Join Our Community</h2>
        <p>Login to read unlimited news and chat with readers</p>

        <div className="social-login">
          <button className="google-btn" onClick={handleGoogle}>
            Continue with Google
          </button>
          <button className="facebook-btn" onClick={handleFacebook}>
            Continue with Facebook
          </button>
        </div>

        <div className="divider">OR</div>

        <button className="email-btn" onClick={handleEmail}>
          Login with Email
        </button>
      </div>
    </div>
  );
};

export default LoginPopup;
